const r = wb.getRange('Data!U3:AI20');
const vals = r.getValues();
const kinds:any = {}; const digitish:string[] = []; const num:any[]=[];
vals.forEach((row:any[],i:number)=>row.forEach((v:any,j:number)=>{
  const t = v===null||v===undefined?'empty':typeof v; kinds[t]=(kinds[t]||0)+1;
  if (typeof v==='number') num.push([i,j,v]);
  if (typeof v==='string' && /^[\s\d.,'-]+$/.test(v)) digitish.push(i+','+j+':'+JSON.stringify(v));
}));
log(JSON.stringify({kinds,num,digitish, sample: vals[12][0], rows:vals.length, cols:vals[0].length}));
log(r.getCounts());
log(wb.evaluate('=SUMPRODUCT(--ISFORMULA(Data!U3:AI20))'));

